-- Back GST out of dump-loaded purchase_price so P&L compares exclusive
-- cost to exclusive sale (22_product_gst.sql already did this for sale_price).
--
-- Reports (report_tables._profit_loss / product profit) do:
--   gross profit = invoice taxable (excl. GST) - qty * product.purchase_price
-- After 22, sale is exclusive and purchase was still the listed pack cost,
-- so a ₹90 pesticide (₹80 cost) billed the farmer ₹90 but showed a loss
-- of ₹3.73. Exclusive purchase ₹67.80 restores the ~₹8.47 GST-free margin.
--
-- Same statutory rates as 22_product_gst.sql (from product.category):
--   seed         0%   — purchase_price unchanged
--   fertilizer   5%
--   pesticide   18%
-- MRP, historical invoice lines, and GRN lot prices are not touched.
-- Opening batches that copied the master listed cost are updated:
--   LEGACY-OPENING (10_batch.sql) and STOCK-ON-HAND (21_stock_on_hand.sql).
--
-- Exclusive price is chosen so listed cost + GST (half-even, 2 dp)
-- matches today's purchase_price. Amounts that cannot hit exactly at
-- 5%/18% land 1 paise under. Zero listed costs stay 0.
--
-- Review before running. Idempotent: skips a row if purchase_price moved
-- or attributes.gst_purchase_backed_out is already true. Run after 22.
-- Safe on an already-loaded DB (22 may already have been applied).
--
--   mysql -u root -p skac_new < deploy/mysql/migrate_from_dump/23_product_purchase_gst.sql
--
-- Products in 08_product.sql: 3887
--   seed 0%:        450
--   fertilizer 5%:  1356
--   pesticide 18%:  2081
-- Rows updated: 3411  (seeds / zero cost / unchanged omitted)
-- Reconstructed vs listed cost: exact 3574  -₹0.01 313  +₹0.01 0
-- purchase > listed sale in dump: 61
-- exclusive purchase > exclusive sale after this script: 61
-- SKUs that looked like a loss after 22 but are profitable exclusive-to-exclusive: 2169

USE skac_new;
SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS product_purchase_gst_fix;
CREATE TEMPORARY TABLE product_purchase_gst_fix (
  id INT PRIMARY KEY,
  new_gst DECIMAL(5,2) NOT NULL,
  old_purchase DECIMAL(12,2) NOT NULL,
  new_purchase DECIMAL(12,2) NOT NULL,
  reconstructed DECIMAL(12,2) NOT NULL
);



















-- Review: exclusive vs listed cost by GST rate.
SELECT f.new_gst AS gst_pct, COUNT(*) AS sku,
       SUM(f.old_purchase) AS listed_cost, SUM(f.new_purchase) AS exclusive_cost,
       SUM(f.reconstructed) AS reconstructed,
       SUM(f.reconstructed) - SUM(f.old_purchase) AS reconstructed_minus_listed
FROM product_purchase_gst_fix f
GROUP BY f.new_gst
ORDER BY f.new_gst;

SELECT p.id, p.sku, p.name, p.category,
       f.old_purchase, f.new_purchase, p.sale_price AS exclusive_sale,
       (f.new_purchase > p.sale_price) AS still_cost_above_sale
FROM product_purchase_gst_fix f
JOIN product p ON p.id = f.id
WHERE f.new_purchase > p.sale_price AND p.sale_price > 0
ORDER BY (f.new_purchase - p.sale_price) DESC, p.name
LIMIT 40;

-- Write. Safe to re-run: only rows still sitting at the dump listed cost.
UPDATE product p
JOIN product_purchase_gst_fix f ON f.id = p.id
SET
  p.purchase_price = f.new_purchase,
  p.attributes = JSON_SET(
    COALESCE(p.attributes, JSON_OBJECT()),
    '$.legacy_purchase_price', f.old_purchase,
    '$.gst_purchase_backed_out', TRUE
  )
WHERE p.organization_id = 1
  AND p.purchase_price = f.old_purchase
  AND IFNULL(JSON_EXTRACT(p.attributes, '$.gst_purchase_backed_out'), FALSE) = FALSE;

SELECT ROW_COUNT() AS products_updated;

-- Opening stock lots copied the master listed cost. Historical GRN lots
-- keep the dump invoice price (may already be exclusive or mixed).
UPDATE batch b
JOIN product_purchase_gst_fix f ON f.id = b.product_id
SET b.purchase_price = f.new_purchase
WHERE b.organization_id = 1
  AND b.batch_no IN ('LEGACY-OPENING', 'STOCK-ON-HAND')
  AND b.purchase_price = f.old_purchase;

SELECT ROW_COUNT() AS opening_batches_updated;

-- Spot-check: exclusive sale vs exclusive purchase vs farmer bill.
SELECT p.id, p.name, p.category, p.gst_rate,
       p.purchase_price, p.sale_price,
       JSON_UNQUOTE(JSON_EXTRACT(p.attributes, '$.legacy_purchase_price')) AS listed_cost_was,
       JSON_UNQUOTE(JSON_EXTRACT(p.attributes, '$.legacy_sale_price')) AS listed_sale_was,
       ROUND(p.sale_price + ROUND(p.sale_price * p.gst_rate / 100, 2), 2) AS billed_sale
FROM product p
JOIN product_purchase_gst_fix f ON f.id = p.id
ORDER BY p.category, p.name
LIMIT 25;
